// Groceries that have a real 3D model (tools/render3d). Their sprite lives in public/food3d/<key>.png.
// Everything else still uses the drawn sticker until its model is built. Regenerated by tools/render3d/render.cjs.
export const REAL3D = new Set(["apple", "tomato", "lemon", "lime", "onion", "red_onion", "garlic", "potato", "sweet_potato", "avocado", "banana", "carrot", "cucumber", "zucchini", "eggplant", "pepper", "green_pepper", "chili", "broccoli", "mushroom", "corn", "cabbage"]);
export const real3dKey = (k) => (k === 'carrots' ? 'carrot' : k);
